// Unico lugar de configuracion del workflow.
// Esta instancia de n8n corre con N8N_BLOCK_ENV_ACCESS_IN_NODE: $env tira
// "access to env vars denied" y el `|| default` NO salva, porque la excepcion
// se tira al tocar $env. Por eso la config vive aca.
// Todo nodo aguas abajo lee con: $('Config').first().json.LO_QUE_SEA
return [{ json: {
  // --- Chatwoot ---
  CHATWOOT_URL: 'https://chatwoot.xtract.app',               // sin barra final, ej: https://app.chatwoot.com
  CHATWOOT_ACCOUNT_ID: '1', // numerico, sale de la URL /app/accounts/<id>/
  CHATWOOT_INBOX_ID: '1',     // inbox de WhatsApp, NO otro canal

  // --- Hoja de control del piloto (pestanas: Enviados WA, Interacciones) ---
  // Pestana de la MISMA planilla de donde salen los leads a contactar.
  // Antes esto venia de Notion; se saco a pedido y el piloto se maneja
  // 100% con la hoja.
  WA_LEADS_TAB: 'Leads Piloto',

  // Pausa entre un envio y el siguiente. NO es cosmetico permite a meta no degradar el numero
  WA_ESPERA_ENTRE_ENVIOS_SEG: 10,

  WA_SHEET_URL: 'https://docs.google.com/spreadsheets/d/1w6wVAuYmHjI8Fk4b3S1VLxAcgSSQkUjHOTrE1enmaP8/edit',

  // --- Plantilla aprobada en Meta ---
  WA_TEMPLATE_NAME: 'reactivacion_closed_lost',
  WA_TEMPLATE_LANG: 'es_AR',
  WA_TEMPLATE_PREVIEW: 'Hola {{1}}, como estas? Te escribo de parte del equipo de Xtract.',

  // --- Barandas del piloto ---
  WA_LIMITE_TANDA: 1,   // maximo de envios por corrida, para no quemar el numero
  WA_SOLO_VERDES: 'true' // solo leads calificados Verde
} }];

// =====================================================================
// ARMA LA TANDA DE ENVIO desde la pestana de leads de la planilla.
// Antes esto leia Notion; se saco a pedido. El normalizador de telefonos
// se conserva TAL CUAL: la hoja puede traer numeros pegados a mano y es
// la unica pieza que evita mandarle un WhatsApp a un numero invalido.
// =====================================================================
const LIMITE = parseInt($('Config').first().json.WA_LIMITE_TANDA) || 20;
const SOLO_VERDES = String($('Config').first().json.WA_SOLO_VERDES || 'true') === 'true';

// normKey: NFD, sin acentos, minusculas, separadores colapsados.
// Los encabezados de la hoja los escribe una persona: "Telefono Normalizado",
// "telefono_normalizado" y "Teléfono normalizado" tienen que ser lo mismo.
const normKey = s => (s || '').toString()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/[\s_\-\/]+/g, ' ').trim();

const normalizarFila = r => {
  const o = {};
  for (const k of Object.keys(r || {})) o[normKey(k)] = r[k];
  return o;
};

// Primer alias que exista y no venga vacio
function campo(fila, ...alias) {
  for (const a of alias) {
    const v = fila[normKey(a)];
    if (v != null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
}

const PREFIJOS = { argentina: '54', uruguay: '598', chile: '56', mexico: '52', colombia: '57', peru: '51', brasil: '55', 'costa rica': '506', ecuador: '593', panama: '507', paraguay: '595', bolivia: '591' };

function normalizarTel(raw, paisStr) {
  let d = (raw || '').toString().replace(/[^0-9]/g, '');
  if (!d) return '';
  if (d.startsWith('00')) d = d.slice(2);
  const pais = (paisStr || '').toString().toLowerCase();
  const clave = Object.keys(PREFIJOS).find(k => pais.includes(k)) || '';
  const pref = PREFIJOS[clave] || '';

  // Si el numero YA trae prefijo de CUALQUIER pais conocido y largo pleno,
  // se respeta lo cargado: el campo Pais puede estar mal (datos a mano).
  const yaInternacional = d.length >= 11 && Object.values(PREFIJOS).some(pf => d.startsWith(pf));

  if (!yaInternacional && pref) {
    if (d.startsWith('0')) d = d.slice(1);
    d = pref + d;
  }
  // Argentina: moviles llevan 9 tras el 54. Sin el 9, WhatsApp lo trata
  // como fijo y el mensaje NO SE ENTREGA (sin error).
  if (d.startsWith('54') && !d.startsWith('549')) {
    d = '549' + d.slice(2);
  }
  if (d.length < 10 || d.length > 15) return '';
  return d;
}

// Dedupe contra lo ya enviado. Solo bloquea los que salieron DE VERDAD:
// una fila con estado 'error' vuelve a entrar en la proxima tanda.
// Si la hoja no existe o no se pudo leer, la lista queda vacia y no se
// bloquea a nadie: es preferible a cortar la tanda entera.
const yaEnviados = new Set();
try {
  for (const it of $('Leer enviados').all()) {
    const r = it.json || {};
    if (!String(r.estado || '').toLowerCase().startsWith('enviado')) continue;
    const t = String(r.telefono || '').replace(/[^0-9]/g, '');
    if (t) yaEnviados.add(t.slice(-8));
  }
} catch (e) {}

const elegibles = [];
const vistos = new Set();   // la hoja puede traer el mismo numero dos veces

for (const item of $('Leer leads del piloto').all()) {
  const f = normalizarFila(item.json);

  const empresa = campo(f, 'Empresa', 'Nombre Oportunidad');
  const nombre  = campo(f, 'Contacto', 'Nombre', 'Nombre KDM (SDR)');
  const pais    = campo(f, 'Pais', 'Pais(*)');
  const calif   = campo(f, 'Calificacion');

  // Si la hoja NO trae la columna de calificacion, NO se filtra: la lista
  // del piloto ya viene filtrada a Verdes. Filtrar por una columna ausente
  // dejaria la tanda vacia sin ningun error visible.
  if (SOLO_VERDES && calif && !calif.toLowerCase().startsWith('verde')) continue;

  const tel = normalizarTel(
    campo(f, 'Telefono Normalizado', 'Telefono', 'Whatsapp KDM'), pais);
  if (!tel) continue;

  const cola = tel.slice(-8);
  if (yaEnviados.has(cola) || vistos.has(cola)) continue;
  vistos.add(cola);

  // Si 'empresa' es un email cargado por error, no puede ir en la plantilla
  const empresaDisplay = (!empresa || empresa.includes('@')) ? (nombre || 'tu empresa') : empresa;
  const primerNombre = campo(f, 'Primer Nombre')
    || (nombre.split(' ')[0] || '').trim()
    || empresaDisplay;

  // El motivo suele traer el mensaje de despedida pegado entero. Es el
  // contexto mas valioso que hay, pero normalizado para no romper el prompt.
  let motivo = campo(f, 'Motivo Perdida', 'Motivo Lost').replace(/\s+/g, ' ').trim();
  if (motivo.length > 600) motivo = motivo.slice(0, 600) + '…';

  elegibles.push({ json: {
    notion_page_id: campo(f, 'notion id', 'notion page id'),
    nombre: nombre || primerNombre,
    primer_nombre: primerNombre,
    empresa: empresaDisplay,
    telefono: tel,
    telefono_e164: '+' + tel,
    motivo_perdida: motivo,
    sistema: campo(f, 'Sistema Actual', 'Sistema', 'Que sistema usan?(*)'),
    pais: pais,
    email: campo(f, 'Email'),
    owner: campo(f, 'Comercial', 'Owner', 'Owner(*)'),
    origen: campo(f, 'Origen'),
    cantidad_facturas: campo(f, 'Facturas Mes', 'Cantidad de facturas', 'Cantidad de facturas(*)'),
    company_size: campo(f, 'Company Size'),
    fecha_discovery: campo(f, 'Fecha Discovery').slice(0, 10),
    fecha_reunion: campo(f, 'Fecha Reunion', 'Fecha Primera Reunion').slice(0, 10),
    fecha_propuesta: campo(f, 'Fecha Propuesta', 'Fecha Envio Propuesta').slice(0, 10),
    dias_desde_perdida: campo(f, 'Dias desde Perdida'),
    hubo_reunion: campo(f, 'Hubo Reunion'),
    link_discovery: campo(f, 'Link Discovery', 'Link a Discovery(*)'),
    calificacion: calif
  } });
}

return elegibles.slice(0, LIMITE);

// =====================================================================
// Saca el contact_id de Chatwoot y lo pega a los datos del lead.
//
// OJO CON EL CRUCE: antes esto cruzaba por indice (metas[idx]) sobre la
// salida de un nodo Merge. El Merge de n8n concatena rama-verdadera y
// rama-falsa, asi que el orden NO es el original: el contact_id de un lead
// terminaba pegado a los datos de otro y se mandaba la plantilla con el
// nombre equivocado.
// Ahora usa el paired item ($('Nodo').item), que n8n mantiene aunque el
// item haya pasado por un IF. Por eso el nodo corre "Once for Each Item":
// .item no existe en modo "All Items".
// =====================================================================
const meta = $('Loop de envio').item.json;
const j = $input.item.json || {};

let contactId = null;
if (Array.isArray(j.payload) && j.payload.length > 0) {
  contactId = j.payload[0].id;                       // busqueda con resultado
} else if (j.payload && j.payload.contact && j.payload.contact.id) {
  contactId = j.payload.contact.id;                  // contacto recien creado
} else if (j.payload && j.payload.id) {
  contactId = j.payload.id;
}

// Sin contact_id no se puede seguir: se descarta el item y este lead queda
// SIN marcar como enviado, asi que entra en la proxima tanda.
if (!contactId) return null;

return { json: Object.assign({}, meta, { contact_id: contactId }) };
